#include <vector>
#include <algorithm>
#include <cmath>
#include <climits>

using namespace std;

class Solution {
public:
    long long minOperations(vector<int>& nums, int x, int k) {
        int n = nums.size();
        vector<long long> costs;
        for (int i = 0; i <= n - x; ++i) {
            vector<int> sub(nums.begin() + i, nums.begin() + i + x);
            sort(sub.begin(), sub.end());
            int med = sub[x / 2];
            long long c = 0;
            for (int v : sub) c += abs(v - med);
            costs.push_back(c);
        }

        long long inf = 1e18;
        vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, inf));
        dp[0][0] = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= k; ++j) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0 && i >= x && dp[i - x][j - 1] != inf) {
                    dp[i][j] = min(dp[i][j], dp[i - x][j - 1] + costs[i - x]);
                }
            }
        }
        return dp[n][k];
    }
};

import java.util.*;

class Solution {
    public long minOperations(int[] nums, int x, int k) {
        int n = nums.length;
        long[] costs = new long[n - x + 1];
        for (int i = 0; i <= n - x; i++) {
            int[] sub = Arrays.copyOfRange(nums, i, i + x);
            Arrays.sort(sub);
            int med = sub[x / 2];
            long c = 0;
            for (int v : sub) c += Math.abs(v - med);
            costs[i] = c;
        }

        long inf = (long) 1e18;
        long[][] dp = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], inf);
        }
        dp[0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0 && i >= x && dp[i - x][j - 1] != inf) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - x][j - 1] + costs[i - x]);
                }
            }
        }
        return dp[n][k];
    }
}

var minOperations = function(nums, x, k) {
    const n = nums.length;
    const costs = [];
    for (let i = 0; i <= n - x; i++) {
        const sub = nums.slice(i, i + x).sort((a, b) => a - b);
        const med = sub[Math.floor(x / 2)];
        let c = 0;
        for (const v of sub) c += Math.abs(v - med);
        costs.push(c);
    }

    const inf = Infinity;
    const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(inf));
    dp[0][0] = 0;
    for (let i = 1; i <= n; i++) {
        for (let j = 0; j <= k; j++) {
            dp[i][j] = dp[i - 1][j];
            if (j > 0 && i >= x && dp[i - x][j - 1] !== inf) {
                dp[i][j] = Math.min(dp[i][j], dp[i - x][j - 1] + costs[i - x]);
            }
        }
    }
    return dp[n][k];
};
